#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    int t;
    cin >> t;
    
    while(t--)
    {
        int n;
        cin >> n;
        
        int fm=INT_MIN, sm = INT_MIN;
        int temp;
        
        vector<int> v(n);
        for(int i=0; i<n; i++)
            cin >> v[i];
        
        vector<int> diff(n);
        
        for(int i=0; i<n-1; i++)
        diff[i] = abs(v[i]-v[i+1]);
        
        diff[n-1] = abs(v[n-1]-v[0]);
        
        for(int i=0; i<n; i++)
        {
            temp = diff[i];
            // fm = max(fm, temp);
            if (temp>sm && temp<fm) sm = temp;
            if (temp>=fm)
            {
                sm = fm;
                fm = temp;
            }
        }
        
        cout << sm << endl;
    }
}
